package com.phoenix.business.web;import com.phoenix.business.domain.Member;import com.phoenix.business.repository.*;import lombok.RequiredArgsConstructor;import org.springframework.web.bind.annotation.*;import java.time.*;import java.util.*;
@RestController @RequestMapping("/api/dashboard") @RequiredArgsConstructor public class DashboardController {private final MemberRepository members;private final PaymentRepository payments;private final AttendanceRepository attendance;@GetMapping public Map<String,Object> get(){LocalDate today=LocalDate.now(),month=today.withDayOfMonth(1);Instant ds=today.atStartOfDay(ZoneOffset.UTC).toInstant(),de=today.plusDays(1).atStartOfDay(ZoneOffset.UTC).toInstant(),ms=month.atStartOfDay(ZoneOffset.UTC).toInstant();Map<String,Object> m=new LinkedHashMap<>();m.put("activeMembers",members.countByStatus(Member.Status.ACTIVE));m.put("expiredMembers",members.countByStatus(Member.Status.EXPIRED));m.put("expiringSoon",members.countByExpiryDateBetween(today,today.plusDays(7)));m.put("todayAttendance",attendance.countByCheckedInAtBetween(ds,de));m.put("todayRevenue",payments.revenue(ds,de));m.put("monthRevenue",payments.revenue(ms,de));m.put("newMembersThisMonth",members.countByJoinDateBetween(month,today));m.put("renewalsThisMonth",payments.countByPaymentDateBetween(ms,de));m.put("recentPayments",payments.findTop10ByOrderByPaymentDateDesc());return m;}}
